THOUGHT: Ah, that's a standard Python dataclass issue. Let me fix the test:

```bash
cat > test_inheritance.py << 'EOF'
import pydantic
from pydantic import BaseModel, Field

print("=== Test: Inheritance with init_var field ===")
@pydantic.dataclasses.dataclass
class BaseFoo:
    bar: str
    baz: str = Field(init_var=True)

@pydantic.dataclasses.dataclass
class DerivedFoo(BaseFoo):
    qux: str = ''  # Give it a default to avoid the dataclass ordering issue

class Model(BaseModel):
    foo: DerivedFoo

model = Model(foo=DerivedFoo('bar', baz='baz', qux='qux'))
print('bar' in model.foo.__pydantic_fields__)  # Expected: True
print('baz' in model.foo.__pydantic_fields__)  # Expected: False
print('qux' in model.foo.__pydantic_fields__)  # Expected: True
print("Actual fields:", list(model.foo.__pydantic_fields__.keys()))

print("\n=== Test: Multiple inheritance levels ===")
@pydantic.dataclasses.dataclass
class GrandParent:
    a: str = Field(init_var=True)

@pydantic.dataclasses.dataclass
class Parent(GrandParent):
    b: str = ''  # Give it a default

@pydantic.dataclasses.dataclass
class Child(Parent):
    c: str = Field(init_var=True)

class Model2(BaseModel):
    child: Child

model2 = Model2(child=Child(a='a', b='b', c='c'))
print('a' in model2.child.__pydantic_fields__)  # Expected: False
print('b' in model2.child.__pydantic_fields__)  # Expected: True
print('c' in model2.child.__pydantic_fields__)  # Expected: False
print("Actual fields:", list(model2.child.__pydantic_fields__.keys()))
EOF
